use trie::Trie;

#[test]
fn test_insert_and_search() {
    let mut t = Trie::new();
    t.insert("apple");
    assert!(t.search("apple"));
    assert!(!t.search("app"));
}

#[test]
fn test_starts_with() {
    let mut t = Trie::new();
    t.insert("apple");
    assert!(t.starts_with("app"));
    assert!(!t.starts_with("apl"));
}

#[test]
fn test_multiple_words() {
    let mut t = Trie::new();
    t.insert("hello");
    t.insert("help");
    assert!(t.search("hello"));
    assert!(t.search("help"));
    assert!(!t.search("hell"));
    assert!(t.starts_with("hel"));
}

#[test]
fn test_empty_trie() {
    let t = Trie::new();
    assert!(!t.search("x"));
    assert!(!t.starts_with("x"));
}

#[test]
fn test_insert_then_prefix_then_full() {
    let mut t = Trie::new();
    t.insert("sea");
    t.insert("seal");
    assert!(t.search("sea"));
    assert!(t.search("seal"));
    assert!(t.starts_with("se"));
    assert!(!t.search("se"));
}
